/**
 * The writer -> reader contract for shell_cwd (#3411).
 *
 * WHY THIS FILE EXISTS. `git-validator-worktree.test.ts` already asserts
 * "commit from a feature-branch worktree (shell_cwd) is not blocked", and it has
 * been green since #2363. In production that path never once executed: the test
 * called a local `writeShellCwdState()` helper, so it validated the READER
 * against state that no writer ever produced. CwdChanged, the hook credited with
 * producing it, does not fire for a `cd` inside a Bash call. Across 1763
 * recorded sessions not one state file contained a shell_cwd.
 *
 * A test that hand-feeds the input a real writer is supposed to generate proves
 * half a contract and reports it as the whole one. So every case below drives
 * the ACTUAL writer (`sessionHeartbeatPublisher`) and never writes state itself,
 * and each one carries the negative control that fails without the fix.
 *
 * Real directories under a temp $HOME, because the writer checks existsSync to
 * distinguish a `cd` that moved the shell from one that failed.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, mkdirSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { basename, join } from 'node:path';
import type { HookContext, HookInput } from '../../types.js';
import { gitValidator } from '../../pretool/bash/git-validator.js';
import { sessionHeartbeatPublisher } from '../../posttool/bash/session-heartbeat-publisher.js';
import { NOOP_CTX } from '../../lib/context.js';
import { getStateFilePath, readSessionState } from '../../lib/session-state.js';

vi.mock('node:child_process', () => ({ execFileSync: vi.fn(() => '') }));
vi.mock('../../lib/git-head.js', () => ({
  readBranchFromHead: vi.fn(),
  readBranchOr: vi.fn(),
}));

import { execFileSync } from 'node:child_process';
import { readBranchOr } from '../../lib/git-head.js';
import { _resetBranchCacheForTesting } from '../../lib/git.js';

const SESSION_ID = 'shell-cwd-contract';
const MSG = 'fix(#3411): tracked cwd';

let tmpHome: string;
let projectDir: string;
let worktreeDir: string;
let prevHome: string | undefined;
let prevProjectDir: string | undefined;

function bashPre(command: string): HookInput {
  return {
    tool_name: 'Bash',
    session_id: SESSION_ID,
    project_dir: projectDir,
    tool_input: { command },
  };
}

function bashPost(command: string): HookInput {
  return { ...bashPre(command), tool_output: '' };
}

function mainCtx(): HookContext {
  return { ...NOOP_CTX, branch: 'main', projectDir };
}

function mockBranches(byDir: Record<string, string>): void {
  vi.mocked(readBranchOr).mockImplementation((dir: string, fallback: string) =>
    dir in byDir ? byDir[dir] : fallback,
  );
}

/** What the writer actually put on disk, never written by this test. */
function trackedCwd(): string | null | undefined {
  const path = getStateFilePath(basename(projectDir), SESSION_ID, tmpHome);
  return readSessionState(path)?.shell_cwd;
}

beforeEach(() => {
  tmpHome = mkdtempSync(join(tmpdir(), 'shellcwd-'));
  projectDir = join(tmpHome, 'project');
  worktreeDir = join(projectDir, '.worktrees', 'wt');
  mkdirSync(worktreeDir, { recursive: true });

  prevHome = process.env.HOME;
  prevProjectDir = process.env.CLAUDE_PROJECT_DIR;
  process.env.HOME = tmpHome;
  process.env.CLAUDE_PROJECT_DIR = projectDir;
  delete process.env.ORCHESTKIT_PROTECTED_BRANCHES;

  vi.mocked(execFileSync).mockReset();
  vi.mocked(execFileSync).mockReturnValue('');
  vi.mocked(readBranchOr).mockReset();
  mockBranches({ [projectDir]: 'main', [worktreeDir]: 'fix/3411-tracked' });
  _resetBranchCacheForTesting();
});

afterEach(() => {
  if (prevHome === undefined) delete process.env.HOME;
  else process.env.HOME = prevHome;
  if (prevProjectDir === undefined) delete process.env.CLAUDE_PROJECT_DIR;
  else process.env.CLAUDE_PROJECT_DIR = prevProjectDir;
  rmSync(tmpHome, { recursive: true, force: true });
});

// ===========================================================================
// The half of the contract that was never tested
// ===========================================================================

describe('the writer actually produces shell_cwd', () => {
  it('starts with no record, so the assertions below are not vacuous', () => {
    expect(trackedCwd()).toBeUndefined();
  });

  it('records a top-level cd from a plain Bash command', () => {
    sessionHeartbeatPublisher(bashPost(`cd ${worktreeDir} && pwd`), NOOP_CTX);
    expect(trackedCwd()).toBe(worktreeDir);
  });

  it('records a RELATIVE cd resolved against the project dir', () => {
    sessionHeartbeatPublisher(bashPost('cd .worktrees/wt'), NOOP_CTX);
    expect(trackedCwd()).toBe(worktreeDir);
  });

  it('does not move on a cd inside sh -c: the parent shell never moved', () => {
    sessionHeartbeatPublisher(bashPost(`cd ${worktreeDir}`), NOOP_CTX);
    sessionHeartbeatPublisher(bashPost(`sh -c 'cd ${projectDir} && pwd'`), NOOP_CTX);
    expect(trackedCwd()).toBe(worktreeDir);
  });

  it('does not move on a cd to a path that does not exist, because that cd failed', () => {
    sessionHeartbeatPublisher(bashPost(`cd ${worktreeDir}`), NOOP_CTX);
    sessionHeartbeatPublisher(bashPost(`cd ${projectDir}/nope`), NOOP_CTX);
    expect(trackedCwd()).toBe(worktreeDir);
  });

  it('drops the record for an unmodelable cd rather than keeping a stale one', () => {
    sessionHeartbeatPublisher(bashPost(`cd ${worktreeDir}`), NOOP_CTX);
    sessionHeartbeatPublisher(bashPost('pushd /tmp'), NOOP_CTX);
    expect(trackedCwd()).toBeNull();
  });

  it('leaves no record for a command that neither cds nor touches git', () => {
    sessionHeartbeatPublisher(bashPost('npm test'), NOOP_CTX);
    expect(trackedCwd()).toBeUndefined();
  });
});

// ===========================================================================
// End to end: the verdict the operator actually experiences
// ===========================================================================

describe('a bare git command after a cd is judged by the worktree branch', () => {
  it('NEGATIVE CONTROL: without the cd, a bare commit on main is still blocked', () => {
    const result = gitValidator(bashPre(`git commit -m "${MSG}"`), mainCtx());
    expect(result.continue).toBe(false);
    expect(JSON.stringify(result)).toContain('BLOCKED');
  });

  it('after the cd, the same bare commit is allowed', () => {
    sessionHeartbeatPublisher(bashPost(`cd ${worktreeDir}`), NOOP_CTX);

    const result = gitValidator(bashPre(`git commit -m "${MSG}"`), mainCtx());
    expect(result.continue).toBe(true);
    expect(JSON.stringify(result)).toContain('fix/3411-tracked');
    expect(JSON.stringify(result)).not.toContain('BLOCKED');
  });

  it('after the cd, a bare push is allowed too', () => {
    sessionHeartbeatPublisher(bashPost(`cd ${worktreeDir}`), NOOP_CTX);

    const result = gitValidator(bashPre('git push'), mainCtx());
    expect(result.continue).toBe(true);
    expect(JSON.stringify(result)).not.toContain('BLOCKED');
  });

  it('cding back to the project dir restores the block', () => {
    sessionHeartbeatPublisher(bashPost(`cd ${worktreeDir}`), NOOP_CTX);
    sessionHeartbeatPublisher(bashPost(`cd ${projectDir}`), NOOP_CTX);

    const result = gitValidator(bashPre(`git commit -m "${MSG}"`), mainCtx());
    expect(result.continue).toBe(false);
    expect(JSON.stringify(result)).toContain('BLOCKED');
  });

  it('a worktree on a protected branch is still blocked', () => {
    mockBranches({ [projectDir]: 'main', [worktreeDir]: 'main' });
    sessionHeartbeatPublisher(bashPost(`cd ${worktreeDir}`), NOOP_CTX);

    const result = gitValidator(bashPre(`git commit -m "${MSG}"`), mainCtx());
    expect(result.continue).toBe(false);
    expect(JSON.stringify(result)).toContain('BLOCKED');
  });
});

// ===========================================================================
// One directory, one branch, one verdict: the bar set in #3411
// ===========================================================================

describe('every spelling of the same command agrees', () => {
  it('all six resolve to the worktree branch and none is denied', () => {
    // The ambient cwd is the worktree, exactly as it is mid-session.
    sessionHeartbeatPublisher(bashPost(`cd ${worktreeDir}`), NOOP_CTX);

    const spellings = [
      `git commit -m "${MSG}"`,
      `git -C ${worktreeDir} commit -m "${MSG}"`,
      `cd ${worktreeDir} && git commit -m "${MSG}"`,
      `cd ${worktreeDir} && git add -A && git commit -m "${MSG}"`,
      `cd .worktrees/wt && git commit -m "${MSG}"`,
      `pwd && git commit -m "${MSG}"`,
    ];

    const denied = spellings.filter((cmd) => {
      _resetBranchCacheForTesting();
      const result = gitValidator(bashPre(cmd), mainCtx());
      return result.continue === false || JSON.stringify(result).includes('BLOCKED');
    });

    expect(denied).toEqual([]);
  });
});
